    // dp (top-down)
    private static Map<String, Integer> dp;
    private static int dfs(int i, int pairs, int[] nums, int p) {
        if (pairs == p) return 0;
        if (i >= nums.length - 1) return Integer.MAX_VALUE;

        String  key = i + "-" + pairs;
        if (dp.containsKey(key)) return dp.get(key);

        int n1 = Math.max(nums[i + 1] - nums[i], dfs(i + 2, pairs + 1, nums, p));
        int n2 = dfs(i + 1, pairs, nums, p);

        int res = Math.min(n1, n2);

        dp.put(key, res);
        return res;
    }
    private static int minimizeMax(int[] nums, int p) {
        Arrays.sort(nums);
        dp = new HashMap<>();
        return dfs(0, 0, nums, p);
    }
